create table public.content_packs (
 id text primary key check (id ~ '^[a-z0-9-]{1,80}$'),
 slug text unique not null,
 metadata jsonb not null,
 question_set jsonb not null,
 published boolean not null default false,
 revision text not null,
 updated_at timestamptz not null default now()
);
create table public.content_pack_versions (
 pack_id text not null references public.content_packs(id),
 version text not null,
 question_set jsonb not null,
 primary key(pack_id,version)
);
alter table public.content_packs enable row level security;
alter table public.content_pack_versions enable row level security;
revoke all on public.content_packs, public.content_pack_versions from public, anon, authenticated;
grant all on public.content_packs, public.content_pack_versions to service_role;

-- One transaction for content, immutable version and commerce. Existing order snapshots survive.
create function public.save_content_pack(p_metadata jsonb, p_questions jsonb, p_expected text)
returns jsonb language plpgsql security invoker set search_path = public as $$
declare previous content_packs; pid text := p_metadata->>'id'; rev text := p_metadata->>'contentVersion';
begin
 perform pg_advisory_xact_lock(hashtextextended(pid,0));
 select * into previous from content_packs where id=pid for update;
 if (previous.id is null and p_expected is not null) or
    (previous.id is not null and previous.revision is distinct from p_expected) then
   return jsonb_build_object('error','conflict');
 end if;
 if previous.id is not null and previous.slug <> p_metadata->>'slug' then
   return jsonb_build_object('error','slug_immutable');
 end if;
 insert into content_packs(id,slug,metadata,question_set,published,revision)
 values(pid,p_metadata->>'slug',p_metadata,p_questions,(p_metadata->>'published')::boolean,rev)
 on conflict(id) do update set metadata=excluded.metadata,question_set=excluded.question_set,
 published=excluded.published,revision=excluded.revision,updated_at=now();
 if (p_metadata->>'published')::boolean then
   insert into content_pack_versions values(pid,rev,p_questions);
 end if;
 if p_metadata->>'tier'='premium' then
   insert into products(pack_id,title,price_vnd,active)
   values(pid,p_metadata->>'title',(p_metadata->>'priceHintVnd')::integer,(p_metadata->>'published')::boolean)
   on conflict(pack_id) do update set title=excluded.title,price_vnd=excluded.price_vnd,
   active=excluded.active,price_version=products.price_version + case when products.price_vnd<>excluded.price_vnd then 1 else 0 end;
 else
   update products set active=false where pack_id=pid;
 end if;
 return jsonb_build_object('ok',true);
end $$;
revoke all on function public.save_content_pack(jsonb,jsonb,text) from public,anon,authenticated;
grant execute on function public.save_content_pack(jsonb,jsonb,text) to service_role;

-- Import the existing catalog once; keep pack/question IDs for saved games and purchases.
select public.save_content_pack('{"id": "friends-free", "slug": "ban-be-khoi-dong", "title": "Bạn bè khởi động", "description": "Những câu hỏi nhẹ nhàng để phá băng và bắt đầu cuộc vui.", "tier": "free", "questionFile": "/content/questions/friends-free/412aef31-5950-4218-a6df-5fa58822c267", "contentVersion": "412aef31-5950-4218-a6df-5fa58822c267", "questionCount": 100, "truthCount": 50, "dareCount": 50, "trialCount": 0, "priceHintVnd": 0, "productId": null, "ageLabel": "16+", "playerRange": {"min": 2, "max": 8}, "published": true, "icon": "🎉", "color": "purple", "categoryIds": ["friends"]}'::jsonb || jsonb_build_object('priceHintVnd',coalesce((select price_vnd from products where pack_id='friends-free'),0)), '{"schemaVersion": 1, "packId": "friends-free", "locale": "vi", "contentVersion": "412aef31-5950-4218-a6df-5fa58822c267", "trialQuestionIds": [], "questions": [{"id": "t01", "type": "truth", "text": "Bạn từng thích thầm ai lâu nhất trong bao lâu?"}, {"id": "t02", "type": "truth", "text": "Điều gì ở một người khiến bạn dễ rung động nhất?"}, {"id": "t03", "type": "truth", "text": "Bạn đã từng giả vờ không thích một người dù thật ra rất thích chưa?"}, {"id": "t04", "type": "truth", "text": "Kỷ niệm tình cảm nào khiến bạn nhớ lâu nhất?"}, {"id": "t05", "type": "truth", "text": "Bạn thích được tỏ tình trực tiếp hay qua tin nhắn hơn?"}, {"id": "t06", "type": "truth", "text": "Nếu được hẹn hò với một người nổi tiếng, bạn sẽ chọn ai?"}, {"id": "t07", "type": "truth", "text": "Bạn từng ghen nhưng cố tỏ ra không quan tâm chưa?"}, {"id": "t08", "type": "truth", "text": "Điều ngọt ngào nhất ai đó từng làm cho bạn là gì?"}, {"id": "t09", "type": "truth", "text": "Bạn có tin tình bạn lâu năm có thể biến thành tình yêu không?"}, {"id": "t10", "type": "truth", "text": "Kiểu tin nhắn nào có thể khiến bạn mỉm cười cả ngày?"}, {"id": "t11", "type": "truth", "text": "Bạn từng chủ động nhắn tin cho crush rồi giả vờ gửi nhầm chưa?"}, {"id": "t12", "type": "truth", "text": "Nếu crush đang ở đây, điều gì bạn muốn nói nhưng có thể không dám nói?"}, {"id": "t13", "type": "truth", "text": "Bạn thích một buổi hẹn lãng mạn hay một buổi hẹn vui nhộn hơn?"}, {"id": "t14", "type": "truth", "text": "Bạn từng đọc lại đoạn chat cũ với người mình thích chưa?"}, {"id": "t15", "type": "truth", "text": "Theo bạn, điểm hấp dẫn nhất của chính mình là gì?"}, {"id": "t16", "type": "truth", "text": "Bạn từng làm điều ngốc nghếch nào để gây chú ý với người mình thích?"}, {"id": "t17", "type": "truth", "text": "Bạn thích người chủ động hay thích tự mình chủ động hơn?"}, {"id": "t18", "type": "truth", "text": "Có lời khen nào bạn từng nhận mà đến giờ vẫn còn nhớ không?"}, {"id": "t19", "type": "truth", "text": "Bạn từng tưởng tượng chuyện yêu đương với một người bạn chưa?"}, {"id": "t20", "type": "truth", "text": "Nếu phải chọn một bài hát mô tả chuyện tình cảm của mình, bạn chọn bài nào?"}, {"id": "t21", "type": "truth", "text": "Bạn dễ bị thu hút bởi ngoại hình hay cách nói chuyện hơn?"}, {"id": "t22", "type": "truth", "text": "Bạn từng stalk trang cá nhân của crush sâu đến mức nào?"}, {"id": "t23", "type": "truth", "text": "Nếu được quay lại một khoảnh khắc với người mình từng thích, bạn chọn lúc nào?"}, {"id": "t24", "type": "truth", "text": "Bạn có thể thích một người hoàn toàn trái gu ban đầu của mình không?"}, {"id": "t25", "type": "truth", "text": "Điều gì khiến bạn mất cảm tình với một người nhanh nhất?"}, {"id": "t26", "type": "truth", "text": "Bạn từng cố tình đăng story chỉ để một người cụ thể xem chưa?"}, {"id": "t27", "type": "truth", "text": "Nếu người yêu cũ nhắn ''Anh/em nhớ em/anh'', phản ứng đầu tiên của bạn là gì?"}, {"id": "t28", "type": "truth", "text": "Bạn thích được nắm tay, ôm hay tựa vai nhất?"}, {"id": "t29", "type": "truth", "text": "Bạn từng có một cuộc trò chuyện đến khuya với ai đó mà không muốn kết thúc chưa?"}, {"id": "t30", "type": "truth", "text": "Theo bạn, ai trong nhóm này có gu ăn mặc hợp với bạn nhất?"}, {"id": "t31", "type": "truth", "text": "Nếu được nhận một món quà bất ngờ từ người mình thích, bạn muốn đó là gì?"}, {"id": "t32", "type": "truth", "text": "Bạn từng thích hai người cùng lúc chưa?"}, {"id": "t33", "type": "truth", "text": "Bạn nghĩ mình dễ yêu hay rất khó rung động?"}, {"id": "t34", "type": "truth", "text": "Nếu phải chọn một người trong nhóm để đi du lịch cùng, bạn chọn ai?"}, {"id": "t35", "type": "truth", "text": "Bạn từng chuẩn bị một tin nhắn rất lâu rồi cuối cùng không gửi chưa?"}, {"id": "t36", "type": "truth", "text": "Một buổi hẹn đầu tiên hoàn hảo với bạn sẽ diễn ra như thế nào?"}, {"id": "t37", "type": "truth", "text": "Bạn thích được gọi bằng biệt danh tình cảm nào?"}, {"id": "t38", "type": "truth", "text": "Bạn từng hiểu nhầm rằng ai đó thích mình chưa?"}, {"id": "t39", "type": "truth", "text": "Bạn có thể yêu xa nếu thật sự thích một người không?"}, {"id": "t40", "type": "truth", "text": "Điều lãng mạn nào bạn muốn trải nghiệm ít nhất một lần?"}, {"id": "t41", "type": "truth", "text": "Bạn từng từ chối ai rồi sau đó cảm thấy tiếc chưa?"}, {"id": "t42", "type": "truth", "text": "Bạn thích cảm giác mới bắt đầu thích nhau hay cảm giác yêu nhau lâu dài hơn?"}, {"id": "t43", "type": "truth", "text": "Nếu phải miêu tả gu của mình bằng ba từ, bạn sẽ chọn từ nào?"}, {"id": "t44", "type": "truth", "text": "Bạn từng mơ thấy người mình thích rồi tỉnh dậy vẫn thấy vui chưa?"}, {"id": "t45", "type": "truth", "text": "Theo bạn, điều khó nói nhất khi thích một người là gì?"}, {"id": "t46", "type": "truth", "text": "Nếu được biết chắc một người trong nhóm từng thích bạn, bạn muốn đó là ai?"}, {"id": "t47", "type": "truth", "text": "Bạn từng lưu ảnh của crush trong điện thoại chưa?"}, {"id": "t48", "type": "truth", "text": "Bạn nghĩ một nụ hôn đầu lý tưởng nên diễn ra trong hoàn cảnh nào?"}, {"id": "t49", "type": "truth", "text": "Nếu chỉ được giữ lại một phẩm chất ở người yêu tương lai, bạn chọn điều gì?"}, {"id": "t50", "type": "truth", "text": "Có điều gì về chuyện tình cảm mà bạn muốn thử nhưng vẫn chưa đủ can đảm?"}, {"id": "d01", "type": "dare", "text": "Nhìn vào mắt một người trong nhóm và nói một lời khen thật lòng."}, {"id": "d02", "type": "dare", "text": "Diễn cảnh tỏ tình với một chiếc gối hoặc đồ vật gần bạn."}, {"id": "d03", "type": "dare", "text": "Hát một đoạn bài hát tình yêu mà bạn nhớ nhất."}, {"id": "d04", "type": "dare", "text": "Tạo dáng như ảnh bìa album tình yêu và giữ nguyên để cả nhóm chụp hình."}, {"id": "d05", "type": "dare", "text": "Chọn một người và diễn cảnh hai bạn vô tình gặp nhau trong phim tình cảm."}, {"id": "d06", "type": "dare", "text": "Nói một câu thả thính tự nghĩ ra với người đối diện."}, {"id": "d07", "type": "dare", "text": "Dùng ba emoji để diễn tả gu người yêu của bạn và để cả nhóm đoán."}, {"id": "d08", "type": "dare", "text": "Nhảy một điệu thật tự tin theo bài hát do cả nhóm chọn."}, {"id": "d09", "type": "dare", "text": "Giả giọng một nhân vật nổi tiếng và nói câu ''Mình thích bạn mất rồi''."}, {"id": "d10", "type": "dare", "text": "Để một người trong nhóm tạo cho bạn một biệt danh mới dùng đến hết cuộc chơi."}, {"id": "d11", "type": "dare", "text": "Diễn tả crush lý tưởng của bạn chỉ bằng hành động để mọi người đoán."}, {"id": "d12", "type": "dare", "text": "Kể một câu chuyện tình yêu tưởng tượng trong đúng ba câu."}, {"id": "d13", "type": "dare", "text": "Tạo một kiểu bắt tay bí mật với người bên cạnh."}, {"id": "d14", "type": "dare", "text": "Nói lời cảm ơn chân thành với một người trong nhóm về điều bạn quý ở họ."}, {"id": "d15", "type": "dare", "text": "Đọc tên mình theo phong cách MC giới thiệu nhân vật chính của phim tình cảm."}, {"id": "d16", "type": "dare", "text": "Tạo một câu slogan quảng cáo bản thân như thể bạn là ''người yêu lý tưởng''."}, {"id": "d17", "type": "dare", "text": "Chọn một người và cùng tạo dáng chụp ảnh kiểu poster phim thanh xuân."}, {"id": "d18", "type": "dare", "text": "Dùng giọng cực kỳ nghiêm túc để đọc một câu thả thính ngớ ngẩn."}, {"id": "d19", "type": "dare", "text": "Mô phỏng biểu cảm của bạn khi crush bất ngờ nhắn ''Tớ cũng thích cậu''."}, {"id": "d20", "type": "dare", "text": "Để cả nhóm chọn một cảm xúc rồi diễn cảm xúc đó như trong phim."}, {"id": "d21", "type": "dare", "text": "Nói ba điều tích cực về người ngồi gần bạn nhất."}, {"id": "d22", "type": "dare", "text": "Tự sáng tác một câu thơ tình có chứa tên của một người trong nhóm."}, {"id": "d23", "type": "dare", "text": "Giả vờ gọi điện cho crush và rủ họ đi hẹn hò."}, {"id": "d24", "type": "dare", "text": "Diễn cảnh bị từ chối lời tỏ tình theo cách hài hước nhất có thể."}, {"id": "d25", "type": "dare", "text": "Chọn một người và cùng nhau tạo hình trái tim bằng tay."}, {"id": "d26", "type": "dare", "text": "Nói một câu khiến bạn nghĩ người khác nghe xong sẽ đỏ mặt."}, {"id": "d27", "type": "dare", "text": "Miêu tả một buổi hẹn hoàn hảo bằng cách đóng vai hướng dẫn viên du lịch."}, {"id": "d28", "type": "dare", "text": "Đóng vai người dẫn chương trình và giới thiệu người bên cạnh như một ngôi sao."}, {"id": "d29", "type": "dare", "text": "Dùng ánh mắt và biểu cảm để thả thính một người mà không được nói."}, {"id": "d30", "type": "dare", "text": "Đứng lên catwalk như đang đi gặp crush trong buổi hẹn đầu tiên."}, {"id": "d31", "type": "dare", "text": "Kể tên một bài hát bạn muốn dành tặng cho một người trong nhóm và nói lý do."}, {"id": "d32", "type": "dare", "text": "Diễn cảnh nhận được tin nhắn từ crush lúc nửa đêm."}, {"id": "d33", "type": "dare", "text": "Tạo một lời chúc ngủ ngon vừa ngọt ngào vừa buồn cười."}, {"id": "d34", "type": "dare", "text": "Để người bên cạnh chọn một từ và biến nó thành câu thả thính."}, {"id": "d35", "type": "dare", "text": "Đóng vai nhân vật chính trong cảnh chia tay nhưng phải khiến cả nhóm bật cười."}, {"id": "d36", "type": "dare", "text": "Dùng một đồ vật gần bạn làm đạo cụ và cầu hôn nó thật trang trọng."}, {"id": "d37", "type": "dare", "text": "Chọn một người và cùng nghĩ tên cho bộ phim tình cảm nếu hai bạn là nhân vật chính."}, {"id": "d38", "type": "dare", "text": "Nói một lời khen với người bạn ít nói chuyện nhất trong nhóm."}, {"id": "d39", "type": "dare", "text": "Thể hiện ba biểu cảm: gặp crush, được crush khen và bị crush seen tin nhắn."}, {"id": "d40", "type": "dare", "text": "Tưởng tượng bạn đang nhận giải ''Người đáng yêu nhất năm'' và phát biểu cảm nghĩ."}, {"id": "d41", "type": "dare", "text": "Chọn một người và đặt cho họ một biệt danh dễ thương kèm lời giải thích."}, {"id": "d42", "type": "dare", "text": "Dùng tên ba món ăn để tạo thành một câu tỏ tình có nghĩa."}, {"id": "d43", "type": "dare", "text": "Diễn lại cách bạn nghĩ mình sẽ phản ứng nếu bất ngờ được tỏ tình."}, {"id": "d44", "type": "dare", "text": "Chọn một người và đấu mắt với họ; ai cười trước là người thua."}, {"id": "d45", "type": "dare", "text": "Tạo một dáng chụp ảnh mà bạn nghĩ sẽ khiến crush chú ý."}, {"id": "d46", "type": "dare", "text": "Đọc một câu bất kỳ trên màn hình bằng giọng lãng mạn nhất có thể."}, {"id": "d47", "type": "dare", "text": "Giả vờ làm chuyên gia tình yêu và đưa ra một lời khuyên hài hước cho cả nhóm."}, {"id": "d48", "type": "dare", "text": "Chọn một người và cùng diễn cảnh chụp ảnh cưới nhưng không được cười."}, {"id": "d49", "type": "dare", "text": "Tự nghĩ một câu mở đầu để làm quen với người lạ mà bạn thật sự dám sử dụng."}, {"id": "d50", "type": "dare", "text": "Gửi một cái ôm bằng động tác hoặc lời nói đến người bạn muốn cảm ơn nhất trong nhóm."}]}'::jsonb, null);
select public.save_content_pack('{"id": "friends-premium", "slug": "ban-be-gan-ket", "title": "Bạn bè gắn kết", "description": "Một chút bất ngờ, một chút chân thành để nhóm bạn hiểu nhau hơn.", "tier": "premium", "questionFile": "/content/questions/friends-premium/fccba702-249d-4cbb-8da1-4022c8178f81", "contentVersion": "fccba702-249d-4cbb-8da1-4022c8178f81", "questionCount": 12, "truthCount": 6, "dareCount": 6, "trialCount": 8, "priceHintVnd": 30000, "productId": "pack-friends-premium", "ageLabel": "16+", "playerRange": {"min": 2, "max": 8}, "published": true, "icon": "💖", "color": "pink", "categoryIds": ["friends"]}'::jsonb || jsonb_build_object('priceHintVnd',coalesce((select price_vnd from products where pack_id='friends-premium'),30000)), '{"schemaVersion": 1, "packId": "friends-premium", "locale": "vi", "contentVersion": "fccba702-249d-4cbb-8da1-4022c8178f81", "trialQuestionIds": ["t01", "t02", "t03", "t04", "d01", "d02", "d03", "d04"], "questions": [{"id": "t01", "type": "truth", "text": "Điều nhỏ bé nào bạn luôn trân trọng ở một người bạn?"}, {"id": "t02", "type": "truth", "text": "Lần gần nhất bạn tự hào về bản thân là khi nào?"}, {"id": "t03", "type": "truth", "text": "Nếu cả nhóm đi du lịch, bạn muốn đến đâu?"}, {"id": "t04", "type": "truth", "text": "Bạn muốn học kỹ năng nào cùng một người bạn?"}, {"id": "t05", "type": "truth", "text": "Một lời khuyên nào đã giúp bạn thay đổi?"}, {"id": "t06", "type": "truth", "text": "Bạn mong nhóm mình cùng thực hiện điều gì trong năm nay?"}, {"id": "d01", "type": "dare", "text": "Gửi một lời cảm ơn trực tiếp đến một người trong nhóm."}, {"id": "d02", "type": "dare", "text": "Hãy quảng cáo một đồ vật gần bạn trong 20 giây."}, {"id": "d03", "type": "dare", "text": "Diễn lại một cảnh phim bằng biểu cảm để nhóm đoán."}, {"id": "d04", "type": "dare", "text": "Tặng mỗi người trong nhóm một biệt danh tích cực."}, {"id": "d05", "type": "dare", "text": "Hãy sáng tác hai câu thơ về cuộc gặp hôm nay."}, {"id": "d06", "type": "dare", "text": "Mời một người tự nguyện cùng bạn tạo một điệu nhảy 10 giây."}]}'::jsonb, null);
select public.save_content_pack('{"id": "premium-18", "slug": "18-plus", "title": "18+", "description": "Những câu hỏi và thử thách dành cho các cặp đôi muốn hâm nóng tình cảm.", "tier": "premium", "questionFile": "/content/questions/premium-18/535e03ef-1227-4a1f-8097-297ed0c02ea5", "contentVersion": "535e03ef-1227-4a1f-8097-297ed0c02ea5", "questionCount": 200, "truthCount": 100, "dareCount": 100, "trialCount": 8, "priceHintVnd": 30000, "productId": "premium-18", "ageLabel": "18+", "playerRange": {"min": 2, "max": 10}, "published": true, "icon": "✨", "color": "orange", "categoryIds": ["couples"]}'::jsonb || jsonb_build_object('priceHintVnd',coalesce((select price_vnd from products where pack_id='premium-18'),30000)), '{"schemaVersion": 1, "packId": "premium-18", "locale": "vi", "contentVersion": "535e03ef-1227-4a1f-8097-297ed0c02ea5", "trialQuestionIds": ["t01", "t02", "t03", "t04", "d01", "d02", "d03", "d04"], "questions": [{"id": "t01", "type": "truth", "text": "Bạn thích bị người kia chạm vào chỗ nào nhất khi đang âu yếm?"}, {"id": "t02", "type": "truth", "text": "Điều gì khiến bạn hứng thú nhất khi nhìn người kia cởi đồ?"}, {"id": "t03", "type": "truth", "text": "Bạn từng tưởng tượng làm chuyện ấy với người kia ở địa điểm công cộng nào?"}, {"id": "t04", "type": "truth", "text": "Bạn thích kiểu hôn nào nhất: nhẹ nhàng, sâu hay đầy dục vọng?"}, {"id": "t05", "type": "truth", "text": "Có bộ phận nào trên cơ thể người kia khiến bạn muốn liếm/hôn ngay lập tức không?"}, {"id": "t06", "type": "truth", "text": "Bạn muốn thử tư thế nào mà cả hai chưa từng làm?"}, {"id": "t07", "type": "truth", "text": "Bạn thích bị người kia nói bẩn vào tai lúc đang làm tình không?"}, {"id": "t08", "type": "truth", "text": "Bạn từng tự sướng nghĩ về người kia chưa? Lần gần nhất là khi nào?"}, {"id": "t09", "type": "truth", "text": "Bạn thích bị người kia cắn nhẹ hay liếm nhiều hơn?"}, {"id": "t10", "type": "truth", "text": "Bạn muốn người kia mặc gì khi hai người ''chơi'' với nhau?"}, {"id": "t11", "type": "truth", "text": "Bạn thích được người kia khen ngợi bộ phận nào trên cơ thể mình nhất?"}, {"id": "t12", "type": "truth", "text": "Bạn từng mơ thấy làm tình với người kia ở đâu?"}, {"id": "t13", "type": "truth", "text": "Bạn thích bị trói nhẹ hoặc bị kiểm soát trong lúc âu yếm không?"}, {"id": "t14", "type": "truth", "text": "Bạn muốn thử dùng đồ chơi tình dục cùng nhau không? Loại nào?"}, {"id": "t15", "type": "truth", "text": "Bạn thích nhìn người kia tự sướng trước mặt mình không?"}, {"id": "t16", "type": "truth", "text": "Bạn thích bị người kia bú/hút mạnh hay nhẹ nhàng hơn?"}, {"id": "t17", "type": "truth", "text": "Bạn từng tưởng tượng người kia làm gì với bạn trong lúc làm tình?"}, {"id": "t18", "type": "truth", "text": "Bạn thích được người kia xoa dầu massage rồi làm chuyện ấy không?"}, {"id": "t19", "type": "truth", "text": "Bạn muốn thử làm tình dưới vòi hoa sen hay trong bồn tắm không?"}, {"id": "t20", "type": "truth", "text": "Bạn thích bị người kia gọi bằng biệt danh dâm đãng nào?"}, {"id": "t21", "type": "truth", "text": "Bạn thích được người kia vuốt ve từ sau lưng hay từ phía trước hơn?"}, {"id": "t22", "type": "truth", "text": "Bạn từng muốn người kia ''thưởng'' bạn bằng miệng sau một ngày dài không?"}, {"id": "t23", "type": "truth", "text": "Bạn thích kiểu quan hệ nhanh và mạnh hay chậm rãi và sâu?"}, {"id": "t24", "type": "truth", "text": "Bạn muốn thử làm tình khi đang xem phim nóng cùng nhau không?"}, {"id": "t25", "type": "truth", "text": "Bạn thích bị người kia giữ chặt tay hoặc chân khi đang làm tình không?"}, {"id": "t26", "type": "truth", "text": "Bạn từng tưởng tượng người kia mặc đồ lót gợi cảm rồi cởi từng món không?"}, {"id": "t27", "type": "truth", "text": "Bạn thích được người kia thì thầm những lời dâm đãng lúc đang ''chơi'' không?"}, {"id": "t28", "type": "truth", "text": "Bạn muốn thử tư thế doggy hay missionery nhiều hơn?"}, {"id": "t29", "type": "truth", "text": "Bạn thích bị người kia liếm từ cổ xuống dưới không?"}, {"id": "t30", "type": "truth", "text": "Bạn từng muốn làm tình với người kia ngay trên bàn hoặc ghế sofa không?"}, {"id": "t31", "type": "truth", "text": "Bạn thích được người kia dùng tay hoặc miệng trước khi vào chuyện chính?"}, {"id": "t32", "type": "truth", "text": "Bạn muốn thử roleplay gì với người kia (ví dụ: sếp-nhân viên, bác sĩ-bệnh nhân…)?"}, {"id": "t33", "type": "truth", "text": "Bạn thích bị người kia ''ăn'' chậm rãi hay nhanh và mạnh?"}, {"id": "t34", "type": "truth", "text": "Bạn từng tưởng tượng người kia làm tình với bạn trong lúc bạn đang ngủ không?"}, {"id": "t35", "type": "truth", "text": "Bạn thích được người kia cắn nhẹ vào mông hoặc đùi không?"}, {"id": "t36", "type": "truth", "text": "Bạn muốn thử làm tình khi đang đứng không?"}, {"id": "t37", "type": "truth", "text": "Bạn thích bị người kia nhìn chằm chằm khi đang cởi đồ không?"}, {"id": "t38", "type": "truth", "text": "Bạn từng muốn người kia quay video ngắn lúc hai người đang âu yếm không?"}, {"id": "t39", "type": "truth", "text": "Bạn thích được người kia xoa kem hoặc dầu lên người rồi mát-xa không?"}, {"id": "t40", "type": "truth", "text": "Bạn muốn thử làm tình ngoài trời (nếu đủ riêng tư) không?"}, {"id": "t41", "type": "truth", "text": "Bạn thích bị người kia dùng ngón tay hay lưỡi nhiều hơn?"}, {"id": "t42", "type": "truth", "text": "Bạn từng tưởng tượng người kia ''thưởng'' bạn ngay khi vừa về nhà không?"}, {"id": "t43", "type": "truth", "text": "Bạn thích được người kia giữ tóc hoặc kéo nhẹ tóc khi đang làm tình không?"}, {"id": "t44", "type": "truth", "text": "Bạn muốn thử 69 với người kia không?"}, {"id": "t45", "type": "truth", "text": "Bạn thích bị người kia nói ''tốt lắm'' hoặc ''ngon quá'' lúc đang ''chơi'' không?"}, {"id": "t46", "type": "truth", "text": "Bạn từng muốn làm tình với người kia ngay trên sàn nhà không?"}, {"id": "t47", "type": "truth", "text": "Bạn thích được người kia bú/hút trong lúc đang xem phim không?"}, {"id": "t48", "type": "truth", "text": "Bạn muốn thử dùng băng bịt mắt khi âu yếm không?"}, {"id": "t49", "type": "truth", "text": "Bạn thích bị người kia vuốt ve từ từ rồi đột ngột mạnh lên không?"}, {"id": "t50", "type": "truth", "text": "Bạn từng tưởng tượng người kia làm tình với bạn trong phòng thay đồ hoặc nhà vệ sinh công cộng không?"}, {"id": "d01", "type": "dare", "text": "Hôn người kia ở cổ và tai trong 20 giây, không được dùng tay."}, {"id": "d02", "type": "dare", "text": "Thì thầm vào tai người kia 3 câu dâm đãng bạn muốn làm với họ."}, {"id": "d03", "type": "dare", "text": "Cởi một món đồ của người kia bằng miệng (nếu cả hai đồng ý)."}, {"id": "d04", "type": "dare", "text": "Ngồi lên đùi người kia và hôn sâu trong 15 giây."}, {"id": "d05", "type": "dare", "text": "Mô tả chi tiết 1 phút cách bạn muốn ''ăn'' người kia tối nay."}, {"id": "d06", "type": "dare", "text": "Chạm vào chỗ nhạy cảm của người kia qua quần áo trong 10 giây."}, {"id": "d07", "type": "dare", "text": "Liếm từ cổ xuống xương đòn của người kia trong 15 giây."}, {"id": "d08", "type": "dare", "text": "Cắn nhẹ vào môi dưới của người kia rồi hôn sâu."}, {"id": "d09", "type": "dare", "text": "Nói 5 điều bạn muốn làm với cơ thể người kia ngay lúc này."}, {"id": "d10", "type": "dare", "text": "Vuốt ve đùi trong của người kia từ từ trong 20 giây."}, {"id": "d11", "type": "dare", "text": "Hôn người kia từ môi xuống cổ, rồi thì thầm một câu bẩn."}, {"id": "d12", "type": "dare", "text": "Cởi áo người kia bằng một tay trong khi hôn họ."}, {"id": "d13", "type": "dare", "text": "Ngồi đối diện người kia và mô tả chi tiết cách bạn muốn họ ''ăn'' bạn."}, {"id": "d14", "type": "dare", "text": "Chạm nhẹ vào nhũ hoa người kia qua áo trong 10 giây."}, {"id": "d15", "type": "dare", "text": "Hôn người kia ở vành tai rồi thì thầm: ''Anh/Em muốn…''."}, {"id": "d16", "type": "dare", "text": "Vuốt ve mông người kia qua quần trong 15 giây."}, {"id": "d17", "type": "dare", "text": "Nói cho người kia biết bạn muốn họ cởi đồ theo thứ tự nào."}, {"id": "d18", 